<?php
namespace Tests\Feature;
use App\Models\{User,Apprentice,Programme,ProgrammeOutcome,HistoricalCohort as Cohort,HistoricalCohortRow as Row};
use App\Support\{HistoricalCohorts as H,ReviewedImports as Hash};
use Illuminate\Foundation\Testing\LazilyRefreshDatabase;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Str;
use Illuminate\Validation\ValidationException;
use Tests\Support\AuditFault;
use Tests\TestCase;
class HistoricalCohortsTest extends TestCase {
 use LazilyRefreshDatabase;
 private function f(int $n=5,string $year='2024'):array {
  $this->travelTo(now()->setDate(2026,11,15)->setTime(10,0));$admin=User::factory()->create(['role'=>'admin']);$checker=User::factory()->create(['role'=>'admin']);$historic=User::factory()->create(['role'=>'tutor','active'=>false,'name'=>'Fictional former tutor']);$current=User::factory()->create(['role'=>'tutor','name'=>'Fictional current tutor']);$programme=Programme::firstOrCreate(['standard_code'=>'TEST48','version'=>'1.0'],['name'=>'Fictional Programme','level'=>3]);$people=[];
  for($i=0;$i<$n;$i++){$a=Apprentice::factory()->create(['programme_id'=>$programme->id,'tutor_id'=>$current->id,'start_date'=>((int)$year-2).'-09-01','planned_end_date'=>$year.'-06-30']);ProgrammeOutcome::factory()->create(['apprentice_id'=>$a->id,'context'=>['status'=>'Completed','achievement'=>'Achieved','endDate'=>$year.'-06-20','achievementDate'=>$year.'-07-01','sourceRef'=>'PRIVATE-OUTCOME-SOURCE48','reason'=>'PRIVATE-CONTEXT48','ehcp'=>'Yes']]);$people[]=$a;}
  $from=$year.'-01-01';$to=$year.'-12-31';$grace=90;return compact('admin','checker','historic','current','programme','people','from','to','grace');
 }
 private function capture(array $f):array{return H::capture($f['admin'],$f['programme']->id,$f['from'],$f['to'],$f['grace']);}
 private function draft(array $f,?string $token=null):Cohort {$s=$this->capture($f);return H::create($f['admin'],1,$f['programme']->id,$f['from'],$f['to'],$f['grace'],$s['source_hash'],$token??(string)Str::uuid(),'PRIVATE-COHORT-SOURCE48');}
 private function checked(array $f,?Cohort $c=null,?int $staff=null):Cohort {$c??=$this->draft($f);$selected=[];foreach(H::rows($c)as$row){$selected[$row->id]=$row->version;}H::editBatch($f['admin'],1,$c,$c->version,$selected,$staff??$f['historic']->id,H::BASES[0],'PRIVATE-HISTORICAL-EVIDENCE48');return $c->refresh();}
 private function approved(array $f):Cohort {$c=$this->checked($f);H::decide($f['checker'],1,$c,$c->version,'approve','PRIVATE-INDEPENDENT-REVIEW48');return $c->refresh();}
 private function reject(callable $fn):void {try{$fn();$this->fail('Expected checked refusal');}catch(ValidationException $e){$this->assertNotEmpty($e->errors());}}
 public function test_read_only_capture_has_no_current_tutor_inference_or_private_context():void {$f=$this->f();$before=DB::table('portal_operations_events')->count();$s=$this->capture($f);$this->assertCount(5,$s['rows']);$this->assertFalse($s['meta']['current_tutor_inferred']);$this->assertStringNotContainsString('PRIVATE-CONTEXT48',json_encode($s));$this->assertStringNotContainsString('ehcp',json_encode($s));$this->assertArrayNotHasKey('tutor_id',$s['rows'][0]);$this->assertSame($before,DB::table('portal_operations_events')->count());$this->assertDatabaseCount('historical_cohorts',0);}
 public function test_draft_freezes_all_members_with_unreviewed_unknown_attribution():void {$f=$this->f();$c=$this->draft($f);$this->assertTrue(H::intact($c));$this->assertCount(5,H::rows($c));foreach(H::rows($c)as$r){$this->assertNull($r->historical_tutor_id);$this->assertFalse($r->details['attribution']['reviewed']);$this->assertTrue(H::rowIntact($r));}$this->assertStringNotContainsString('PRIVATE-COHORT-SOURCE48',DB::table('historical_cohorts')->value('details'));}
 public function test_evidence_records_inactive_historical_tutor_without_changing_live_assignment():void {$f=$this->f();$c=$this->checked($f);foreach(H::rows($c)as$r){$this->assertSame($f['historic']->id,$r->historical_tutor_id);$this->assertSame($f['historic']->name,$r->details['attribution']['staff_name']);$this->assertTrue($r->details['attribution']['reviewed']);}$this->assertSame($f['current']->id,$f['people'][0]->fresh()->tutor_id);$this->assertFalse($f['historic']->fresh()->active);}
 public function test_independent_approval_exports_known_mature_cohort_with_exact_denominator():void {$f=$this->f();$c=$this->approved($f);$r=H::report($f['admin'],$c);$this->assertSame(5,$r['counts']['mature']);$this->assertSame(5,$r['counts']['achieved']);$this->assertEquals(100,$r['groups'][0]['achievement_percent']);$this->assertFalse($r['official_qar']);$this->assertFalse($r['causal_staff_effectiveness']);$this->assertFalse($r['apprentice_identities_in_export']);}
 public function test_aggregate_omits_learner_identity_and_private_references():void {$f=$this->f();$f['people'][0]->update(['reference'=>'PRIVATE-LEARNER48','first_name'=>'PRIVATE-NAME48']);$r=H::report($f['admin'],$this->approved($f));$json=json_encode($r);foreach(['PRIVATE-LEARNER48','PRIVATE-NAME48','PRIVATE-OUTCOME-SOURCE48','PRIVATE-COHORT-SOURCE48','PRIVATE-HISTORICAL-EVIDENCE48','PRIVATE-INDEPENDENT-REVIEW48','PRIVATE-CONTEXT48','apprentice_id','"members":','creator_auth']as$secret){if($secret==='apprentice_id'){$this->assertStringNotContainsString('"apprentice_id":',$json);}else{$this->assertStringNotContainsString($secret,$json);}}}
 public function test_small_sample_withholds_percentage_instead_of_displaying_zero():void {$f=$this->f(4);$r=H::report($f['admin'],$this->approved($f));$this->assertSame(4,$r['counts']['achieved']);$this->assertNull($r['achievement_percent']);$this->assertNull($r['groups'][0]['achievement_percent']);}
 public function test_withdrawn_and_transferred_remain_in_mature_denominator():void {$f=$this->f();foreach(['Withdrawn','Transferred']as$i=>$status){ProgrammeOutcome::where('apprentice_id',$f['people'][$i]->id)->first()->update(['context'=>['status'=>$status,'endDate'=>'2024-06-20','sourceRef'=>'Fictional checked end source']]);}$r=H::report($f['admin'],$this->approved($f));$this->assertSame(5,$r['counts']['mature']);$this->assertSame(3,$r['counts']['achieved']);$this->assertSame(1,$r['counts']['withdrawn']);$this->assertSame(1,$r['counts']['transferred']);$this->assertEquals(60,$r['achievement_percent']);}
 public function test_late_achievement_is_separate_and_withholds_window_percentage():void {$f=$this->f();$o=ProgrammeOutcome::where('apprentice_id',$f['people'][0]->id)->first();$d=$o->context;$d['achievementDate']='2024-12-01';$o->update(['context'=>$d]);$r=H::report($f['admin'],$this->approved($f));$this->assertSame(1,$r['counts']['after_window']);$this->assertSame(4,$r['counts']['achieved']);$this->assertNull($r['achievement_percent']);}
 public function test_late_end_is_not_assumed_to_be_a_known_outcome_within_window():void {$f=$this->f();$o=ProgrammeOutcome::where('apprentice_id',$f['people'][0]->id)->first();$o->update(['context'=>['status'=>'Withdrawn','endDate'=>'2024-12-01','sourceRef'=>'Fictional later outcome']]);$r=H::report($f['admin'],$this->approved($f));$this->assertSame(1,$r['counts']['after_window']);$this->assertSame(0,$r['counts']['withdrawn']);$this->assertNull($r['achievement_percent']);}
 #[\PHPUnit\Framework\Attributes\TestWith(['Active'])]
