 public function test_open_current_outcomes_are_pending_not_success_or_failure(string $status):void {$f=$this->f();ProgrammeOutcome::where('apprentice_id',$f['people'][0]->id)->first()->update(['context'=>['status'=>$status,'sourceRef'=>'Fictional checked open status']]);$r=H::report($f['admin'],$this->approved($f));$this->assertNull($r['achievement_percent']);$this->assertSame(4,$r['counts']['achieved']);}
 public function test_awaited_and_invalid_results_withhold_percentage():void {$f=$this->f();foreach(['Awaiting result','Unknown']as$i=>$result){ProgrammeOutcome::where('apprentice_id',$f['people'][$i]->id)->first()->update(['context'=>['status'=>'Completed','endDate'=>'2024-06-20','achievement'=>$result,'sourceRef'=>'Fictional checked completion']]);}$r=H::report($f['admin'],$this->approved($f));$this->assertSame(1,$r['counts']['awaiting_result']);$this->assertSame(1,$r['counts']['unknown']);$this->assertNull($r['achievement_percent']);}
 public function test_shared_or_unknown_responsibility_is_explicit_and_never_dropped():void {$f=$this->f();$c=$this->draft($f);$rows=H::rows($c);H::edit($f['admin'],1,$c,$rows[0],$c->version,1,null,H::BASES[1],'Fictional shared responsibility source');$c->refresh();$selected=[];foreach(array_slice(H::rows($c),1)as$r){$selected[$r->id]=1;}H::editBatch($f['admin'],1,$c,$c->version,$selected,$f['historic']->id,H::BASES[0],'Fictional checked historical assignment');$c->refresh();H::decide($f['checker'],1,$c,$c->version,'approve','Fictional independent full cohort check');$r=H::report($f['admin'],$c);$this->assertSame(5,$r['counts']['cohort']);$this->assertSame(1,$r['unknown_or_shared_attributions']);$unknown=collect($r['groups'])->firstWhere('staff_key','unknown');$this->assertSame(1,$unknown['counts']['achieved']);$this->assertNull($unknown['achievement_percent']);}
 public function test_unchecked_attributions_hold_approval():void {$f=$this->f();$c=$this->draft($f);$this->reject(fn()=>H::decide($f['checker'],1,$c,1,'approve','Fictional independent review'));$this->assertSame('Draft',$c->fresh()->state);}
 public function test_self_review_refused_for_admin_but_explicit_ceo_override_is_audited():void {$f=$this->f();$c=$this->checked($f);$this->reject(fn()=>H::decide($f['admin'],1,$c,$c->version,'approve','Fictional self review',true));$ceo=User::factory()->create(['role'=>'ceo']);$f['admin']=$ceo;$c=$this->checked($f);$this->reject(fn()=>H::decide($ceo,1,$c,$c->version,'approve','Fictional CEO review without override'));H::decide($ceo,1,$c,$c->version,'approve','Fictional explicit CEO self-review',true);$this->assertTrue($c->fresh()->proof['decision']['ceo_self_override']);}
 public function test_changed_outcome_after_capture_holds_approval():void {$f=$this->f();$c=$this->checked($f);ProgrammeOutcome::where('apprentice_id',$f['people'][0]->id)->first()->update(['context'=>['status'=>'Active','sourceRef'=>'Fictional source correction']]);$this->reject(fn()=>H::decide($f['checker'],1,$c,$c->version,'approve','Fictional independent source review'));}
 public function test_new_matching_member_or_revised_planned_date_holds_approval():void {$f=$this->f();$c=$this->checked($f);Apprentice::factory()->create(['programme_id'=>$f['programme']->id,'start_date'=>'2022-01-01','planned_end_date'=>'2024-08-01']);$this->reject(fn()=>H::decide($f['checker'],1,$c,$c->version,'approve','Fictional membership review'));}
 public function test_approved_snapshot_never_reloads_live_outcomes_or_current_tutor():void {$f=$this->f();$c=$this->approved($f);$before=H::report($f['admin'],$c);ProgrammeOutcome::where('apprentice_id',$f['people'][0]->id)->first()->update(['context'=>['status'=>'Active','sourceRef'=>'Fictional later correction']]);$f['people'][0]->update(['planned_end_date'=>'2025-06-30','tutor_id'=>$f['checker']->id]);$this->assertSame($before,H::report($f['admin'],$c));}
 public function test_withdrawn_report_is_unavailable_even_with_an_older_model_instance():void {$f=$this->f();$c=$this->approved($f);H::decide($f['checker'],1,$c,$c->version,'withdraw','Fictional report correction needed');$this->assertSame('Withdrawn',$c->fresh()->state);$this->reject(fn()=>H::report($f['admin'],$c));$this->assertNotNull($c->fresh()->proof['decision']['previous_decision']);}
 public function test_rejection_retains_capture_but_cannot_export_an_approved_report():void {$f=$this->f();$c=$this->draft($f);H::decide($f['checker'],1,$c,1,'reject','Fictional source needs recapture');$this->assertDatabaseCount('historical_cohort_rows',5);$this->reject(fn()=>H::report($f['admin'],$c->fresh()));}
 public function test_exact_capture_replay_returns_same_draft_and_changed_reference_is_refused():void {$f=$this->f();$s=$this->capture($f);$token=(string)Str::uuid();$c=$this->draft($f,$token);$again=$this->draft($f,$token);$this->assertSame($c->id,$again->id);$this->reject(fn()=>H::create($f['admin'],1,$f['programme']->id,$f['from'],$f['to'],90,$s['source_hash'],$token,'Fictional changed reference'));$this->assertDatabaseCount('historical_cohorts',1);}
 public function test_wrong_staff_basis_null_combinations_are_refused():void {$f=$this->f();$c=$this->draft($f);$r=H::rows($c)[0];$this->reject(fn()=>H::edit($f['admin'],1,$c,$r,1,1,null,H::BASES[0],'Fictional missing staff'));$this->reject(fn()=>H::edit($f['admin'],1,$c,$r,1,1,$f['historic']->id,H::BASES[2],'Fictional invalid attribution'));}
 public function test_foreign_cohort_row_cannot_be_edited_or_batched():void {$f=$this->f();$a=$this->draft($f);$b=$this->draft($f);$r=H::rows($b)[0];$this->reject(fn()=>H::edit($f['admin'],1,$a,$r,1,1,$f['historic']->id,H::BASES[0],'Fictional wrong cohort'));$this->reject(fn()=>H::editBatch($f['admin'],1,$a,1,[$r->id=>1],$f['historic']->id,H::BASES[0],'Fictional wrong cohort batch'));}
 public function test_stale_cohort_and_row_versions_hold_edits():void {$f=$this->f();$c=$this->draft($f);$r=H::rows($c)[0];H::edit($f['admin'],1,$c,$r,1,1,$f['historic']->id,H::BASES[0],'Fictional first attribution');$this->reject(fn()=>H::edit($f['admin'],1,$c,$r,1,1,null,H::BASES[2],'Fictional stale attribution'));$this->reject(fn()=>H::edit($f['admin'],1,$c->fresh(),$r,2,1,null,H::BASES[2],'Fictional stale row'));}
 public function test_batch_stale_row_rolls_back_every_prior_row_and_header_version():void {$f=$this->f();$c=$this->draft($f);$rows=H::rows($c);usort($rows,fn($a,$b)=>strcmp($a->id,$b->id));$selected=[$rows[0]->id=>1,$rows[1]->id=>99];$this->reject(fn()=>H::editBatch($f['admin'],1,$c,1,$selected,$f['historic']->id,H::BASES[0],'Fictional whole batch evidence'));$this->assertSame(1,$c->fresh()->version);foreach(H::rows($c->fresh())as$r){$this->assertFalse($r->details['attribution']['reviewed']);}}
 public function test_attribute_revision_keeps_prior_reference_and_snapshot_source():void {$f=$this->f();$c=$this->checked($f);$r=H::rows($c)[0];$before=$r->details['source'];H::edit($f['admin'],1,$c,$r,$c->version,$r->version,null,H::BASES[2],'Fictional revised uncertain attribution');$r->refresh();$this->assertSame($before,$r->details['source']);$this->assertCount(2,$r->details['history']);$this->assertSame('PRIVATE-HISTORICAL-EVIDENCE48',$r->details['history'][1]['attribution']['reference']);}
 public function test_missing_recorded_end_is_separate_from_the_defined_cohort():void {$f=$this->f();Apprentice::factory()->create(['programme_id'=>$f['programme']->id,'planned_end_date'=>null]);$s=$this->capture($f);$this->assertCount(5,$s['rows']);$this->assertSame(1,$s['meta']['missing_planned_end_outside_cohort']);}
 public function test_future_observation_window_and_bad_dates_are_kept_as_not_mature():void {$f=$this->f();$f['people'][0]->update(['start_date'=>'2025-01-01']);$s=$this->capture($f);$this->assertTrue($s['rows'][0]['date_check']);$c=$this->approved($f);$r=H::report($f['admin'],$c);$this->assertSame(1,$r['counts']['date_check']);$this->assertSame(1,$r['counts']['not_mature']);$this->assertNull($r['achievement_percent']);}
