 public function test_tampered_header_state_and_row_hash_are_refused():void {$f=$this->f();$c=$this->draft($f);DB::table('historical_cohorts')->where('id',$c->id)->update(['state'=>'Approved']);$this->assertFalse(H::intact($c->fresh()));$this->reject(fn()=>H::rows($c->fresh()));}
 public function test_deleted_or_added_captured_row_breaks_the_membership_manifest():void {$f=$this->f();$c=$this->draft($f);Row::where('cohort_id',$c->id)->first()->delete();$this->reject(fn()=>H::rows($c));}
 public function test_tampered_approved_attribution_never_uses_live_fallback():void {$f=$this->f();$c=$this->approved($f);$row=H::rows($c)[0];DB::table('historical_cohort_rows')->where('id',$row->id)->update(['historical_tutor_id'=>$f['current']->id]);$this->reject(fn()=>H::report($f['admin'],$c));}
 public function test_cohort_creation_audit_failure_rolls_back_rows_and_header():void {$f=$this->f();AuditFault::install('historical_create_fault','portal_operations_events','fictional audit fault','historical_cohort_created');try{$this->draft($f);$this->fail('Expected database failure');}catch(\Illuminate\Database\QueryException){}$this->assertDatabaseCount('historical_cohorts',0);$this->assertDatabaseCount('historical_cohort_rows',0);}
 public function test_batch_final_audit_failure_restores_all_rows():void {$f=$this->f();$c=$this->draft($f);AuditFault::install('historical_batch_fault','portal_operations_events','fictional audit fault','historical_attribution_batch');try{$this->checked($f,$c);$this->fail('Expected database failure');}catch(\Illuminate\Database\QueryException){}$this->assertSame(1,$c->fresh()->version);foreach(H::rows($c->fresh())as$r){$this->assertSame(1,$r->version);$this->assertNull($r->historical_tutor_id);}}
 public function test_approval_audit_failure_leaves_draft_and_all_evidence():void {$f=$this->f();$c=$this->checked($f);AuditFault::install('historical_approve_fault','portal_operations_events','fictional audit fault','historical_cohort_approve');try{H::decide($f['checker'],1,$c,$c->version,'approve','Fictional approval reference');$this->fail('Expected database failure');}catch(\Illuminate\Database\QueryException){}$this->assertSame('Draft',$c->fresh()->state);$this->assertNull($c->approved_at);$this->assertCount(5,H::rows($c));}
 public function test_approved_rows_cannot_be_edited():void {$f=$this->f();$c=$this->approved($f);$r=H::rows($c)[0];$this->reject(fn()=>H::edit($f['admin'],1,$c,$r,$c->version,$r->version,null,H::BASES[2],'Fictional attempted rewrite'));}
