 public function test_noncanonical_managers_cannot_open_or_post_historical_reports(string $role):void {$u=User::factory()->create(['role'=>$role]);$this->actingAs($u)->get('/reports/historical-cohorts')->assertForbidden();$this->postJson('/reports/historical-cohorts/preview',[])->assertForbidden();}
 public function test_other_manager_can_review_but_cannot_edit_creators_draft():void {$f=$this->f();$c=$this->draft($f);$r=H::rows($c)[0];$this->actingAs($f['checker'])->postJson('/reports/historical-cohorts/'.$c->id.'/rows/'.$r->id,['version'=>1,'row_version'=>1,'basis'=>H::BASES[0],'historical_tutor_id'=>$f['historic']->id,'reference'=>'Fictional wrong editor','confirmed'=>1])->assertForbidden();}
 public function test_http_pages_render_private_headers_and_json_omits_learner_data():void {$f=$this->f();$c=$this->approved($f);$this->actingAs($f['admin'])->get('/reports/historical-cohorts')->assertOk()->assertSee('Historical staff comparisons')->assertHeader('Referrer-Policy','no-referrer');$root='/reports/historical-cohorts/'.$c->id;$this->get($root)->assertOk()->assertSee('Open approved report');$this->get($root.'/report')->assertOk()->assertSee('100.0%');$this->get($root.'/aggregate.json')->assertOk()->assertJsonPath('official_qar',false)->assertDontSee('PRIVATE-OUTCOME-SOURCE48');}
 public function test_http_approved_report_is_a_real_server_rendered_pdf_without_private_fields():void {$f=$this->f();$c=$this->approved($f);$r=$this->actingAs($f['admin'])->get('/reports/historical-cohorts/'.$c->id.'/report.pdf')->assertOk()->assertHeader('Content-Type','application/pdf');$this->assertStringStartsWith('%PDF',$r->getContent());}
 public function test_filters_refuse_as_of_reconstruction_current_tutor_and_overlong_intervals():void {$f=$this->f();$this->actingAs($f['admin'])->postJson('/reports/historical-cohorts/preview',['programme'=>$f['programme']->id,'from'=>$f['from'],'to'=>$f['to'],'grace'=>90,'as_of'=>'2024-01-01','tutor'=>$f['current']->id])->assertUnprocessable();$this->reject(fn()=>H::capture($f['admin'],$f['programme']->id,'2020-01-01','2024-12-31',90));}
 public function test_release_check_remains_read_only_and_not_target_approval():void {$r=\App\Support\Release48Check::report();$this->assertSame('48',$r['pack']);$this->assertFalse($r['actual_target_acceptance']);$this->assertFalse($r['writes_performed']);$this->assertTrue($r['checks']['route:historical-cohorts.compare']);$this->artisan('gta:release-check48')->assertSuccessful();}
 public function test_separate_mature_cohorts_compare_evidenced_tutor_rates_in_points():void {$f=$this->f(5,'2023');$a=$this->approved($f);$g=$this->f(5,'2024');$g['historic']=$f['historic'];ProgrammeOutcome::where('apprentice_id',$g['people'][0]->id)->first()->update(['context'=>['status'=>'Withdrawn','endDate'=>'2024-06-20','sourceRef'=>'Fictional withdrawal evidence']]);$b=$this->approved($g);$cmp=H::compare($g['admin'],$a,$b);$this->assertCount(1,$cmp['groups']);$this->assertEquals(-20,$cmp['groups'][0]['percentage_point_change']);$this->assertSame(5,$cmp['groups'][0]['earlier']['counts']['mature']);$this->assertSame(4,$cmp['groups'][0]['later']['counts']['achieved']);$this->actingAs($g['admin'])->get('/reports/historical-cohorts/compare?earlier='.$a->id.'&later='.$b->id)->assertOk()->assertSee('-20.0');}
 public function test_comparison_refuses_same_cohort_and_reversed_periods():void {$f=$this->f();$a=$this->approved($f);$this->reject(fn()=>H::compare($f['admin'],$a,$a));$g=$this->f(5,'2023');$b=$this->approved($g);$this->reject(fn()=>H::compare($f['admin'],$a,$b));}
 public function test_programme_version_mismatch_refuses_cross_cohort_rate_comparison():void {$f=$this->f(5,'2023');$a=$this->approved($f);$g=$this->f(5,'2024');$g['programme']->update(['version'=>'2.0']);$b=$this->approved($g);$this->reject(fn()=>H::compare($f['admin'],$a,$b));}
 public function test_observation_window_mismatch_refuses_comparison():void {$f=$this->f(5,'2023');$a=$this->approved($f);$g=$this->f(5,'2024');$g['grace']=30;$b=$this->approved($g);$this->reject(fn()=>H::compare($f['admin'],$a,$b));}
 public function test_unequal_cohort_interval_lengths_refuse_comparison():void {$f=$this->f(5,'2023');$a=$this->approved($f);$g=$this->f(5,'2024');$g['from']='2024-06-01';$g['to']='2024-06-30';$b=$this->approved($g);$this->reject(fn()=>H::compare($f['admin'],$a,$b));}
 public function test_not_mature_capture_cannot_be_compared_after_time_passes():void {$f=$this->f(5,'2023');$f['to']='2023-11-15';$a=$this->approved($f);$g=$this->f(5,'2026');$g['to']='2026-11-15';$g['from']='2026-01-01';$g['people'][0]->update(['planned_end_date'=>'2026-11-01']);$b=$this->approved($g);$this->travel(120)->days();$this->reject(fn()=>H::compare($g['admin'],$a,$b));$this->assertSame(1,H::report($g['admin'],$b)['counts']['not_mature']);}
 public function test_revised_planned_end_cannot_count_same_apprentices_twice():void {$f=$this->f(5,'2023');$a=$this->approved($f);foreach($f['people']as$person){$person->update(['planned_end_date'=>'2024-06-30']);}$f['from']='2024-01-01';$f['to']='2024-12-31';$b=$this->approved($f);$this->reject(fn()=>H::compare($f['admin'],$a,$b));}
 public function test_missing_staff_on_one_side_does_not_create_a_zero_rate():void {$f=$this->f(5,'2023');$a=$this->approved($f);$g=$this->f(5,'2024');$b=$this->approved($g);$cmp=H::compare($f['admin'],$a,$b);$this->assertCount(2,$cmp['groups']);foreach($cmp['groups']as$row){$this->assertNull($row['percentage_point_change']);}}
 public function test_source_change_between_preview_and_create_refuses_capture():void {$f=$this->f();$s=$this->capture($f);$f['people'][0]->update(['planned_end_date'=>'2024-07-01']);$this->reject(fn()=>H::create($f['admin'],1,$f['programme']->id,$f['from'],$f['to'],90,$s['source_hash'],(string)Str::uuid(),'Fictional stale preview'));$this->assertDatabaseCount('historical_cohorts',0);}
 public function test_timetable_only_centre_manager_has_no_historical_report_authority():void {$f=$this->f();$u=User::factory()->create(['role'=>'manager']);\App\Support\TimetableGovernance::role($f['admin'],1,$u,0,1,'centre_manager',false,false,'Fictional timetable remit');$this->actingAs($u)->get('/reports/historical-cohorts')->assertForbidden();}
 public function test_row_hashes_are_bound_to_independent_approval_manifest():void {$f=$this->f();$c=$this->approved($f);$row=H::rows($c)[0];$d=$row->details;$d['attribution']['reference']='Fictional changed after approval';$row->details=$d;$row->details_hash=Hash::hash($d);$row->save();$this->assertTrue(H::rowIntact($row));$this->reject(fn()=>H::report($f['admin'],$c));}
 public function test_bad_programme_metadata_and_empty_or_overlarge_batches_refused():void {$f=$this->f();$c=$this->draft($f);$this->reject(fn()=>H::editBatch($f['admin'],1,$c,1,[],null,H::BASES[2],'Fictional no rows'));$selected=[];for($i=0;$i<26;$i++){$selected[(string)Str::uuid()]=1;}$this->reject(fn()=>H::editBatch($f['admin'],1,$c,1,$selected,null,H::BASES[2],'Fictional too many rows'));$f['programme']->update(['version'=>'']);$this->reject(fn()=>$this->capture($f));}
 public function test_review_pages_escape_saved_evidence():void {$f=$this->f(1);$c=$this->draft($f);$row=H::rows($c)[0];H::edit($f['admin'],1,$c,$row,1,1,null,H::BASES[2],'<script>PRIVATE-EVIDENCE48</script>');$this->actingAs($f['admin'])->get('/reports/historical-cohorts/'.$c->id.'/rows/'.$row->id)->assertOk()->assertSee('&lt;script&gt;PRIVATE-EVIDENCE48&lt;/script&gt;',false)->assertDontSee('<script>PRIVATE-EVIDENCE48</script>',false);}
 public function test_review_pagination_is25_and_full_membership_stays_checked():void {$f=$this->f(26);$c=$this->draft($f);$this->actingAs($f['admin'])->get('/reports/historical-cohorts/'.$c->id)->assertOk()->assertSee('Captured cohort records -25 per page');$this->assertCount(26,H::rows($c));}
 public function test_window_boundary_includes_events_on_cutoff_exactly():void {$f=$this->f();$o=ProgrammeOutcome::where('apprentice_id',$f['people'][0]->id)->first();$d=$o->context;$d['achievementDate']='2024-09-28';$o->update(['context'=>$d]);$r=H::report($f['admin'],$this->approved($f));$this->assertSame(0,$r['counts']['after_window']);$this->assertSame(5,$r['counts']['achieved']);}
 public function test_independent_rejection_can_close_a_stale_creator_draft_without_approving_it():void {$f=$this->f();$c=$this->draft($f);$f['admin']->forceFill(['active'=>false,'auth_version'=>2])->save();H::decide($f['checker'],1,$c,1,'reject','Fictional stale maker draft closure');$this->assertSame('Rejected',$c->fresh()->state);$this->assertCount(5,H::rows($c));$this->reject(fn()=>H::report($f['checker'],$c));}
}
